UPDATE dataset_image SET is_deleted = TRUE, updated_at = #{updatedAt}, updated_by = #{updatedBy}
WHERE image_id = #{imageId} AND dataset_id = #{datasetId} AND is_deleted = FALSE
  AND EXISTS (SELECT 1 FROM dataset WHERE dataset.dataset_id = #{datasetId} AND )


UPDATE dataset_image SET description = #{description,jdbcType=VARCHAR}, updated_at = #{updatedAt}, updated_by = #{updatedBy}
WHERE image_id = #{imageId} AND dataset_id = #{datasetId} AND is_deleted = FALSE
  AND EXISTS (SELECT 1 FROM dataset WHERE dataset.dataset_id = #{datasetId} AND )
